import{_ as t,o,c as a,a2 as d}from"./chunks/framework.BM5YPQmL.js";const h=JSON.parse('{"title":"3.0.0-WP06g3 — 真机修复批次（ocse_enc_fix）","description":"","frontmatter":{},"headers":[],"relativePath":"zh/release/3.0.0-WP06g3.md","filePath":"zh/release/3.0.0-WP06g3.md"}'),r={name:"zh/release/3.0.0-WP06g3.md"};function c(n,e,s,i,l,g){return o(),a("div",null,[...e[0]||(e[0]=[d('<h1 id="_3-0-0-wp06g3-—-真机修复批次-ocse-enc-fix" tabindex="-1">3.0.0-WP06g3 — 真机修复批次（ocse_enc_fix） <a class="header-anchor" href="#_3-0-0-wp06g3-—-真机修复批次-ocse-enc-fix" aria-label="Permalink to &quot;3.0.0-WP06g3 — 真机修复批次（ocse_enc_fix）&quot;">​</a></h1><p>事后剖析批次：WP06g2 现场测试的七起真机灾难，逐字节根因 定位并修复。外加每条路径上的恢复环境，以及 g3 的原始 目标（OCSE/OCIRE 编码修复）。</p><h2 id="变更内容" tabindex="-1">变更内容 <a class="header-anchor" href="#变更内容" aria-label="Permalink to &quot;变更内容&quot;">​</a></h2><ul><li><strong>磁盘探测匹配真实 PC（4.1）。</strong> AHCI 探测不再匹配单一 精确的 PCI 类码：RAID/RST 模式 SATA 控制器（类 0x0104， 许多品牌机的出厂默认）现在可见，与经典的 0x010601 并列。 NVMe 在真机容忍路径上获得超时重试和 disable-CC 重写。 而且探测不再是黑盒：每个 AHCI 和 NVMe 控制器事件都记录到 <strong>串口行</strong>（q35+AHCI 测试组在串口上显示 8 行 <code>ahci:</code>， 旧内核显示零行）。</li><li><strong><code>serial_encoding utf8|gbk</code>（4.2）。</strong> 内核串口输出默认 UTF-8，按需转换为 GBK——中文串口工具（按约定是 GBK） 现在能干净地渲染 <code>lang zh</code>。OCSE 的 <code>ocse_out</code> 采用同一 标准（一套策略，不是两套）。</li><li><strong>VMware 启动崩溃（4.3）。</strong> OCBL 实模式栈现在顶在 0x8E00（低于每个观测到的 EBDA），启动状态监视器读取 BDA 0x40E 的 EBDA 基址，并在大 EBDA 会与状态区重叠时 禁用自己的状态区。等待用户的真机 确认。</li><li><strong>OCIRE 在每条路径上（4.4）。</strong> 主 ISO 携带 <code>/boot/ocire.elf</code>；OCBL 菜单扫描并列出 &quot;OCIRE recovery&quot;； 安装器写入<strong>专属恢复分区</strong>（从磁盘未分配的尾部新切割， FAT32，恢复内核流式写入其上——流式副本在本批落地，起因 是 zh 字体增长暴露了固定缓冲读取）。安装后的 磁盘带两个条目启动。</li><li><strong>编辑器真正本地化（4.5）。</strong> 共享编辑器核心中 21 条硬编码 的英文 UI 字符串改经 <code>tr_()</code> 路由；nano 的图例、提示与 快捷键在 <code>lang zh</code> 下是中文。</li><li><strong>真正的 IME 预编辑缓冲（4.6）。</strong> 拼音绝不进入文本：它 在状态栏上渲染的预编辑条中组词（连同候选与 IME 状态），失败的 IME 服务调用会报告，而不是把字母静默漏进 文件。</li><li><strong>差分渲染（4.7）。</strong> nano 栏经 ANSI 定位钉在最后一行， 只重绘变化的部分：测得的按键流每个字母携带<strong>零</strong>个换行 （事后剖析测得每键 3 行滚动、每会话 8 次全栏 打印）。</li><li><strong>OCSE/OCIRE 编码修复（4.8，g3 的原始目标）。</strong> 破坏整串 转换的破折号映射（GB2312 0xA1AA 与 U+2014）在 OCSE 表和 主内核字体 blob 两边都修复了；OCIRE 获得了汉字字体、 UTF-8 解码和 zh 字符串（它的&quot;乱码&quot;是能力缺失）。支持 zh 的 ocire.elf 大了 6 倍——见上面的流式安装器修复。</li><li><strong>工具（4.9）。</strong> 发布启动门禁重新匹配真实的串口 横幅；&quot;branches: ain]&quot; 这个 CI 工作流残留查明是终端誊录 幻影（字面 <code>[m</code> 被当作 ANSI 复位序列吃掉）——已做字节级 审计，从 KNOWN_ISSUES 退役。</li><li><strong>内核窗口瘦身。</strong> 九个约 16-18 KiB 的静态 TLS 记录 缓冲移到堆上（恒等窗口已收窄到 24 KiB；CI 的 gcc-13 越过了它）。瘦身内核上 HTTPS e2e 7/7。</li></ul><h2 id="资产-sha256" tabindex="-1">资产（SHA256） <a class="header-anchor" href="#资产-sha256" aria-label="Permalink to &quot;资产（SHA256）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>资产</th><th>大小</th><th>SHA256</th></tr></thead><tbody><tr><td>opencube-3.0.0-WP06g3.iso</td><td>4210688</td><td>34bcccdbcf8f66ab9e70bcb8c9a516a4a491d28c3dd9b47d970ee1b37c93fef9</td></tr><tr><td>ocse-3.0.0-WP06g3.iso</td><td>5038080</td><td>0abb622cf3e88641db227fcec1082ecdfa42c367d6eb85247524e4a3923cf3ff</td></tr><tr><td>OpenCubeOS-src-3.0.0-WP06g3.zip</td><td>6106241</td><td>bb533f9f058844eee7baf9fefa794158fed2802fad9eeaf99cddbb13bc8b9297</td></tr><tr><td>OpenCubeOS-3.0.0-WP06g3-update.tar.gz</td><td>1411653</td><td>76f1e35a11204befe4396c1b17377a2c19c298d8f9200cecee27891e6ec10fd0</td></tr></tbody></table><h2 id="证据" tabindex="-1">证据 <a class="header-anchor" href="#证据" aria-label="Permalink to &quot;证据&quot;">​</a></h2><p><code>evidence/3_0_0_wp06g3_ocse_enc_fix/</code>——事后剖析复现（串口 字节转储、屏幕转储）与逐修复的测试组日志（磁盘探测串口、 编码字节流、带切出恢复分区的安装 E2E、编辑器重构流 + 截图、OCIRE zh）。</p>',8)])])}const b=t(r,[["render",c]]);export{h as __pageData,b as default};
